	@ParameterizedTest(name = "foreign-thread operation={0}")
	@ValueSource(strings = { "next", "scalar-seek", "tuple-seek", "stop", "close" })
	void rejectedForeignThreadSeekLeavesOwnerCursorUnchanged(String operation) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig()
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(false));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			var values = repository.getValueFactory();
			var first = values.createIRI("urn:thread-count:first");
			var second = values.createIRI("urn:thread-count:second");
			try (var connection = repository.getConnection()) {
				connection.begin();
				connection.add(first, first, first);
				connection.add(second, second, second);
				connection.commit();
			}
			try (var dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
				NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
				long secondId = source.idOf(second);
				assertThat(Long.compareUnsigned(source.idOf(first), secondId)).isNegative();
				LmdbPrefixRunPlan plan = source.prefixRunPlan(new int[] { TripleIndex.PRED_IDX }, -1, -1, -1, -1);
				try (LmdbPrefixRunCursor runs = source.prefixRuns(plan, -1, -1, -1, -1, true)) {
					AtomicReference<Throwable> rejected = new AtomicReference<>();
					Thread foreign = Thread.ofPlatform().start(() -> {
						try {
							switch (operation) {
							case "next" -> runs.next();
							case "scalar-seek" -> runs.seekTo(secondId);
							case "tuple-seek" -> runs.seekTo(new long[] { secondId });
							case "stop" -> runs.stopBefore(new long[] { secondId });
							case "close" -> runs.close();
							default -> throw new AssertionError(operation);
							}
						} catch (Throwable failure) {
							rejected.set(failure);
						}
					});
					foreign.join();
					assertThat(rejected.get()).isInstanceOf(IllegalStateException.class);
					assertThat(runs.seekTo(secondId)).isTrue();
					assertThat(runs.next()).isTrue();
					assertThat(runs.quad()[TripleIndex.PRED_IDX])
							.as("a rejected foreign-thread operation must not alter the owner's positioning state")
							.isEqualTo(secondId);
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void defaultNativeGroupedQueryConsumesExactIndexRuns() throws Exception {
		Map<String, Long> small = groupedQueryWork("small-query", 8);
		Map<String, Long> large = groupedQueryWork("large-query", 1024);
		assertThat(small.get("representativeQuads")).isEqualTo(2L);
		assertThat(large.get("representativeQuads")).isEqualTo(2L);
		assertThat(large.get("keyPrefixesRead")).isLessThan(2048L);
		assertThat(large.get("leafPagesRead") + large.get("leafHeadersRead") + large.get("pageCacheHits"))
				.as("executed prefix grouping reads validated index pages, including reuse from query planning")
				.isPositive();
	}

	private Map<String, Long> groupedQueryWork(String name, int runSize) throws Exception {
		LmdbStore store = new LmdbStore(directory.resolve(name).toFile(), new LmdbStoreConfig()
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(false));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			var values = repository.getValueFactory();
			try (var connection = repository.getConnection()) {
				connection.begin();
				for (int index = 0; index < runSize; index++) {
					for (String predicate : new String[] { "first", "second" }) {
						connection.add(values.createIRI("urn:index-query:s:" + index),
								values.createIRI("urn:index-query:" + predicate), values.createLiteral(index));
					}
				}
				connection.commit();
				var query = connection.prepareTupleQuery("SELECT ?p (COUNT(*) AS ?c) WHERE { ?s ?p ?o } GROUP BY ?p");
				((SailQuery) query).setLmdbResultCacheRequested(false);
				assertThat(findStrategy(query.explain(Explanation.Level.Telemetry).toGenericPlanNode()))
						.isEqualTo("prefixRunGroups");
				LmdbPrefixRunPlan.resetMetrics();
				try (LmdbStartupReadCounter reads = new LmdbStartupReadCounter()) {
					var rows = QueryResults.asList(query.evaluate());
					assertThat(rows).hasSize(2);
					for (var row : rows) {
						assertThat(((Literal) row.getValue("c")).longValue()).isEqualTo(runSize);
					}
					Map<String, Long> work = work("default", name, runSize, true, true, reads.operations());
					work.put("representativeQuads", LmdbPrefixRunPlan.ROWS_SCANNED.get());
					return work;
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	private static String findStrategy(GenericPlanNode node) {
		String value = node.getStringMetricActual("nativeExecutionPath");
		if (value != null) {
			return value;
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				String found = findStrategy(child);
				if (found != null) {
					return found;
				}
			}
		}
		return null;
	}

